{"code": "import os

# Check the whole data directory for any real image files
def is_real_image(filepath):
    """Check if a file is a real image (not a Git LFS pointer)"""
    try:
        with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
            content = f.read(100)
            if 'git-lfs.github.com' in content:
                return False
    except:
        pass
    return True

train_dir="data/signature-verification-dataset/sign_data/train"
test_dir="data/signature-verification-dataset/sign_data/test"

real_files = []
for root, dirs, files in os.walk(train_dir):
    for f in files:
        filepath = os.path.join(root, f)
        if is_real_image(filepath):
            real_files.append(filepath)

print(f"Found {len(real_files)} real image files out of all files")
print(f"Sample real files: {real_files[:5] if real_files else 'None'}")"}

